const D: MvBook[] = [{"u":"Молитва святому апостолу Фомі","e":"Prayer to the Holy Apostle Thomas","secs":[{"h":"Тропар, глас 2","ps":["Учени́ко Христо́в бив, Боже́ственнаго собо́ра апо́стольськаго соприча́стник, / неві́рствієм бо Христо́во Воскресе́ніє ізвісти́в, / і того́ пречи́стую страсть осяза́нієм уві́рив, Фомо́ всехва́льне, // і ни́ні нам проси́ ми́ра і ве́лія ми́лости."]},{"h":"Кондак, глас 4","ps":["Прему́дрости благода́ті іспо́лнен / Христо́в апо́стол, і служи́тель і́стинний, / в покая́нії вопія́ше Тебі́: // Ти мой єси́ Бог же і Госпо́дь."]},{"h":"Молитва","ps":["О благознамени́тий і сла́вний апо́столе Христо́во Фомо́! Єгда́ на коне́ць віко́в к челові́ком прише́дий Бог ізбра́ тя в ученики́ Своя́ і даде́ ті власть боля́щия ісціля́ти, прокаже́нния очища́ти, ме́ртвия воскреша́ти, бі́си ізгоня́ти, тогда́ не сих ра́ди, но найпа́че любо́вію приліпи́лся єси́ ко Христу́, жела́нієм вожделі́в да́же до сме́рти слі́довати по Нем. Сего́ ра́ди, а́ще попуще́нієм Боже́ственним і не зрел єси́ со іни́ми ученики́ воскре́сшаго Спа́са, а́ще і отре́клся єси́ ві́ровати сему́, до́ндеже вложи́ши перст свой в я́зви гвозди́нния і вложи́ши ру́ку свою́ в ре́бра Єго́, оба́че іспо́лни Госпо́дь проше́ніє се́рдця твоєго́ і непрело́жно па́ки ві́ру твою́ утверди́. Ті́мже мо́лим тя: отве́рзи нам о́чі ві́ри, да плотськи́м неви́димая яв'я́ться нам; пода́ждь нам наде́жду на снисхожде́ніє Бо́жиє, да отча́яніє гріхо́вноє не пожре́ть ни; откри́й нам блаже́нство любве́, я́же кріпка́ єсть, я́ко смерть, і єди́на возмога́єть над то́ю, да порабо́тавше Христу́ на землі́, воздви́гнем і ми себі́ кро́ви Небе́сния і с тобо́ю і всі́ми святи́ми просла́вим пречестно́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва","ps":["О святи́й апо́столе Христо́во Фомо́! Мо́лим тя: сохрани́ і соблюди́ нас моли́твами твої́ми от іскуше́ній дия́вольських і паде́ній гріхо́вних і іспроси́ нам, раба́м Бо́жиїм (імена́), сви́ше по́мощ во вре́м'я неві́рія, да не преткне́мся о ка́мень собла́зна, но неукло́нно ше́ствуєм спаси́тельним путе́м за́повідей Христо́вих, до́ндеже дости́гнем о́них блаже́нних оби́телей ра́йських. Єй, апо́столе Спа́сов! Не посрами́ нас, но бу́ди нам помо́щник і покрови́тель во всем житії́ на́шем і помози́ нам благоче́стно і богоуго́дно житіє́ сіє́ вре́менноє сконча́ти, христия́нськую кончи́ну получи́ти і до́браго отві́та сподо́битися на Стра́шнім Суді́ Христо́ві; да просла́вим великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О святи́й уго́дниче Бо́жий, апо́столе Фомо́! По́двигом до́брим подвиза́вся на землі́, восприя́л єси́ на Небесі́х віне́ць пра́вди, єго́же угото́вал єсть Госпо́дь всім лю́б'ящим Єго́. Ті́мже взира́юще на святи́й твой о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтим святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всеми́лостивому Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і помощі́ нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́каго зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Іоанну Многостраждальному","e":"Prayer to St John the Long-Suffering","secs":[{"h":"Тропар, глас 1","ps":["Терпі́нія столп воі́стину непоколеби́мий, / і забра́ло от вра́жиїх стріля́ній необори́мо, / равноа́нгельне і многострада́льне о́тче наш Іоа́нне, / іму́ще тя, ми, недосто́йнії, мо́лимся, / припа́дающе к честни́м твої́м моще́м те́плі, // ізба́ви нас душетлі́нних страсте́й плотськи́х і спаси́ твої́ми моли́твами."]},{"h":"Кондак, глас 2","ps":["Столп цілому́дрія, вра́жіїми боре́ньми непобіди́мь сий, / а́ки столп, многострада́льноє водруже́нно оста́вил єси́ нам ті́ло твоє́, / всече́стне Іоа́нне, / єму́же в не́мощіх душе́вних і тіле́сних покланя́ющеся, / мо́лим тя, преподо́бне: // моли́ Христа́ Бо́га непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О, святи́й преподо́біє о́тче Іоа́нне! Мно́го пострада́л ти ра́ди ді́вства, томи́мий стра́стію плотсько́й і по́двигами ра́зними удруча́я себ'я́. Посліди́ в глубо́кую вшел і по пле́чі земле́ю себ'я́ заси́пал єси́ і та́ко в лю́том страда́нії всю святу́ю четиредеся́тницю преби́л єси́. В світоно́сную же ноч Воскресе́нія Христо́ва осія́л тя Боже́ственний світ і го́лос Бо́жий бил к тебі́, і ісче́зла борба́ по́хоті тіле́сной с того́ часа́, і світ тот преби́л с тобо́ю до само́й кончи́ни. О, Іоа́нні преподо́біє, мно́гими страда́ніями страсть тіле́сную побіди́в, бу́ди засту́пником і помо́щником одержи́мим по́хотію і вожделі́нієм стра́стним, но хотя́щим лу́чше умре́ти, не́жели согріши́ти. Свободи́ страда́льцев сих, Іоа́нне многострада́льне, пода́й їм терпі́ніє, даби́ не па́дая і не ослабіва́я переноси́ли они́ борбу́ сію́, і моли́ Го́спода, да ізба́вить Он їх із пучи́ни страсте́й і от бре́нія нечистоти́. Отгони́ от них сластолюби́виє о́брази і упраздни́ страсть, подавля́ющую їх, і внуши́ їм уві́реніє, я́ко Госпо́дь сверх си́ли не попуска́єть челові́ку іскуша́тися, і ізба́ви їх от уни́нія, да ісцели́вшись, про́чеє вре́м'я живота́ проведу́ть в поко́є. Осіни́ їх наде́ждою бу́дущего сві́та, і наста́ви їх упова́нієм на Обітова́нную Зе́млю Небе́сную, да просла́в'ять Єди́наго в Тро́йці Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Амвросію, єпископу Медіоланському","e":"Prayer to St Ambrose, Bishop of Milan","secs":[{"h":"Тропар, глас 4","ps":["Пра́вило ві́ри і о́браз кро́тости, / воздержа́нія учи́теля / яви́ тя ста́ду твоєму́, / я́же веще́й і́стина. / Сего́ ра́ди стяжа́л єси́ смире́нієм висо́кая, / нището́ю бога́тая, / о́тче Амвро́сіє, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Боже́ственними догма́ти облиста́я, / помрачи́л єси́ А́рієву пре́лесть, священнотаї́нниче і па́стирю Амвро́сіє; / чудоді́йствуя же си́лою Ду́ха, / стра́сті разли́чния я́ві ісціли́л єси́, о́тче преподо́бне, // Христа́ Бо́га моли́ спасти́ся душа́м на́шим."]},{"h":"Інший кондак, глас 8","ps":["Ізря́дно сло́во жи́зні стяжа́в, о́тче му́дре, / не усумні́ся висоти́ ца́рськия, богонаказа́тельне царя́ обличи́ і умудри́в. / Тім па́че че́стне почте́ся і люде́й свої́х па́ству к Бо́гу наста́ви. / Сего́ ра́ди зове́м ті: // ра́дуйся, Амвро́сіє преди́вне."]},{"h":"Молитва","ps":["О пресла́вний чудотво́рче, в ско́рбіх ско́рий помо́щниче і усе́рдний о ми́рі к Бо́гу моли́твенниче, о́тче святи́й Амвро́сіє! Ві́ми, я́ко ве́ліє ко Спа́су і́маши дерзнове́ніє, предстоя́ го́рнему Престо́лу Єго́, і сего́ ра́ди смире́нно припа́даєм ті: моли́ся Єму́, уго́дниче Бо́жий, да пода́сть наро́ду Українському благоде́нственноє і ми́рноє житіє́, да ізба́вить от враг ви́димих і неви́димих, от наше́ствія іноплеме́нних, от неду́га і гла́да, от вся́кия ско́рби і смертоно́сния я́зви і от вся́каго зла; нам же всім, ві́рою пра́зднующим святу́ю па́м'ять твою́ і усе́рдно хода́тайства твоєго́ ча́ющим, да ниспо́слеть вся благопотре́бная ко вре́менному і ві́чному житію́ на́шему, па́че же оставле́ніє гріхо́в, мир по́мислов, тишину́ серде́чную, здра́віє душа́м і тілесе́м на́шим. Єй, святи́телю Бо́жий, па́стирю Христо́в ми́лостивейший, покрови́телю наш гото́війший! Усли́ши нас, єще́ єди́наго от тебе́ прося́щих: бу́ди те́плий моли́твенник і предста́тель ко Го́споду о духо́вних па́стиріх і отці́х на́ших (імена́), і́же не́мощі на́ша но́сять і о нас боле́знують, до́ндеже вообрази́ться в нас Христо́с, да сохрани́ть Он, всеблаги́й і вся могу́щий Влади́ка, дража́йшия дні житія́ їх в неруши́мом ми́рі і крі́пости сил духо́вних і тіле́сних, да приведе́ть нас, недосто́йних рабо́в Свої́х, їх окормле́нієм і моли́твами, твої́м же хода́йтайством і заступле́нієм ко приста́нищу жи́зні несконча́ємия, іді́же херуви́ми і серафи́ми, святі́ї всі с Богоро́дицею і с тобо́ю, покрови́телем на́шим, непреста́нними гла́си сла́в'ять Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О всесвяти́й Амвро́сіє, уго́дниче Бо́жий ізря́днійший, покрови́телю мой ми́лостивейший! При́зри с висоти́ го́рняго жили́ща твоєго́ на м'я недосто́йнаго, неради́ваго, уни́лаго в настоя́щем житії́ сем. Виждь мене́ грі́шнаго, в толи́цім обстоя́нії су́щаго, умо́м помраче́ннаго, во́лею ко злу преклоне́ннаго, і се́рдцем па́че к землі́, не́же к небесі́, прилепле́ннаго. Виждь стра́стноє обурева́ніє душі́ моєя́ і не́мощ і небреже́ніє моє́. Виждь при сем і кова́рство злонача́льника і губи́теля моєго́, виждь, о святи́телю Христо́в, і умилосе́рдися о мні, такова́го ра́ди положе́нія моєго́. Помози́ мі, о засту́пниче мой, ско́рим предста́тельством твої́м. Ісхода́тайствуй мі от Отця́ щедро́т бо́дрость і си́лу, во є́же твори́ти во́лю Єго́, благу́ю, уго́дную і соверше́нную, стра́сті моя́ умертви́ти, де́мона низложи́ти, мир себі́ расп'я́ти і себі́ ми́ру, і та́ко дости́гнути христия́нськия кончи́ни живота́ своєго́, безболі́зненни, непости́дни, ми́рни. По ісхо́ді же притре́петния душі́ моєя́ от окая́ннаго і бре́ннаго тілесе́ сего́, бу́ди єй а́нгел покрови́тель, добр спу́тник, ві́рен храни́тель і защи́тник от лю́тих нападе́ній нача́льника возду́шних мита́рств, да безбі́дно преше́д о́ния, си́лою предста́тельства твоєго́, сподо́блюся про́чеє і аз, послі́дній із всіх, і́же в ца́рстві благода́ті, узрі́ти сладча́йшеє лице́ Го́спода на́шего і сла́вити Єго́ со Отце́м і Святи́м Ду́хом, і твоє́ ми́лостивноє о мні предста́тельство, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Макарію Великому, Єгипетському","e":"Prayer to St Macarius the Great of Egypt","secs":[{"h":"Тропар, глас 1","ps":["Пусти́нний жи́тель і во пло́ті А́нгел, / і чудотво́рець яви́лся єси́, Богоно́се о́тче наш Мака́ріє, / посто́м, бді́нієм, моли́твою, Небе́сная дарова́нія приї́м, / ісціля́єши неду́жния і ду́ші ві́рою приходя́щих ті. / Сла́ва Да́вшему тебі́ крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Кондак, глас 4","ps":["В дому́ Госпо́дь воздержа́нія воі́стинну тя положи́, / я́коже звізду́ непреле́стную, світоводя́щу конці́, // о́тче отце́в, Мака́ріє преподо́бне."]},{"h":"Інший кондак, глас 1","ps":["Блаже́нную жизнь сконча́во в житії́ с му́ченичеськими ли́ки, / в землі́ кро́тких досто́йно водворя́єшися, Богоно́сне Мака́ріє, / і пусти́ню, я́коже град насели́в, благода́ть прия́л єси́ от Бо́га чуде́с, // ті́мже тя почита́єм."]},{"h":"Молитва","ps":["О преподо́бне о́тче Мака́ріє! Мо́лим тя ми, недосто́йниє, іспроси́ предста́тельством твої́м у Всеми́лостиваго Бо́га на́шего нам здра́віє душе́вноє і тіле́сноє, ти́хоє і богоуго́дноє житіє́ і до́брий отві́т на Стра́шнім Суді́ Христо́ві. Угаси́ моли́твами твої́ми разжже́ниє на рабо́в Бо́жиїх (імена́) стрі́ли дия́вольськия, да не прико́снеться нам зло́ба гріхо́вная, да благоче́стно сконча́вше вре́менноє житіє́, сподо́бимся наслі́довати Ца́рствіє Небе́сноє і ку́пно с тобо́ю сла́вити Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Антонію Сійському","e":"Prayer to St Anthony of Siya","secs":[{"h":"Тропар, глас 1","ps":["Жела́нієм духо́вним распали́вся / і м'яте́жи мирськи́я отри́нув, / ко єди́ному же Бо́гу любо́вію приліпи́лся єси́, / і, Того́ вседу́шні взиску́я, / во вну́треннюю пусти́ню отше́л єси́, при вода́х всели́вся, / іді́же во слеза́х і труді́х пребива́я многолі́тноє вре́м'я, / в терпі́нії мно́зім житіє́ а́нгельськоє проходи́л єси́, / в наставле́нії Боже́ственнаго ра́зума: / і мно́жество мона́хов собра́л єси́, му́дре, / ї́хже посіща́я не оста́ви, Анто́ніє преподо́бне о́тче наш, / Пресвяті́й Тро́йце моля́ся // от зол вся́чеських ізба́вити і спасти́ ду́ші на́ша."]},{"h":"Інший тропар, глас 6","ps":["І́же воі́стину на землі́ тя А́нгела / і на Небесі́ челові́ка Бо́жия почти́м, / сію́ жизнь су́єтную оста́вль, / я́ко воі́стину преудо́брен во́їн Христа́ Бо́га, / на стра́сті душепа́губния подвиза́вся в жи́зні сей су́єтній / бді́нієм і поще́нієм, / во всем бив о́браз свої́м ученико́м. / Ті́мже бо в тя всели́ся Пресвяти́й Дух, / Єго́же ді́йствієм сві́тло укра́шен, / но я́ко імі́я дерзнове́ніє ко Святі́й Тро́йці, / помина́й святу́ю оби́тель сію́ / і ста́до своє́, є́же собра́, му́дре, / і не забу́ди, я́коже обіща́ся, / посіща́й чад свої́х, // Анто́ніє преподо́бне, о́тче наш."]},{"h":"Кондак, глас 8","ps":["От ю́ности, преподо́бне, плоть твою́ в пості́х і моли́твах істончи́л єси́ / і крест твой взем, Христу́ послі́довал єси́, / ті́мже і к Ви́шнім тече́ніє ра́достно соверши́л єси́, / іді́же со всі́ми святи́ми Святі́й Тро́йці предстої́ши; / і ни́ні ста́до твоє́ посіща́я, / помина́й чту́щих пресвяту́ю па́м'ять твою́, / да всі благода́рні вопіє́м ті: // ра́дуйся, Богому́дре Анто́ніє, наста́вниче пусти́нний."]},{"h":"Інший кондак, глас 3","ps":["Христа́ єди́наго вожделі́в, / і к Тому́ любо́вію уязви́вся, / і Тому́ неотло́жним путе́м послі́довал єси́. / Вся́коє жите́йськоє наслажде́ніє возненави́дів, / ті́мже, я́ко второ́є со́лнце, чудеси́ сія́я, / і сего́ ра́ди тя да́ром обогати́ Влади́ка, / помина́й нас, чту́щих пресві́тлую па́м'ять твою́, да зове́м ті: // ра́дуйся, Анто́ніє, преподо́бне о́тче наш."]},{"h":"Молитва перша","ps":["О преди́вний чудотво́рче і вели́кий уго́дниче Бо́жий, преподо́бне о́тче Анто́ніє, па́стирю наш до́брий, те́плий засту́пниче і ско́рий помо́щниче, предстоя́й Престо́лу Святи́я Тро́йці, при́зри ми́лостивим о́ком на ни і на вся лю́ди, благогові́йні притека́ющия к честно́му гро́бу твоєму́, в не́мже лежа́щия святи́я мо́щі твоя́, от дній дре́вніх цвіту́ще нетлі́нієм і благоуха́юще благода́тію животворя́щаго Пресвята́го Ду́ха, неоску́дно істоча́ють ісціле́нія от вся́ких неду́гов душе́вних і тіле́сних, усли́ши нас, моля́щахся і чту́щих святу́ю па́м'ять твою́. Моли́ ми́лостиваго Бо́га, отврати́ти от нас вся́кий гнів Єго́, пра́ведно на ни дви́жимий, і сохрани́ти не то́чію оби́тель на́шу, но і вся гра́ди і ві́си, і вся стра́ни христия́нськия і лю́ди, живу́щия в них, от гра́да і гла́да, от тру́са і пото́па, от огня́ і меча́, от наше́ствія іноплеме́нних і междоусо́бния бра́ні, от смертоно́сния я́зви і вся́кия па́губи і вся́каго зла, дарова́ти же нам вся к жи́зні вре́менній благопотре́бная і к ві́чному спасе́нію поле́зная. Помози́ нам, свя́тче Бо́жий, ізбіжа́ти па́губних сіте́й дия́вольських, препобіди́ти собла́зни ми́ра і умертви́ти у́ди на́ша, су́щия на землі́; отврати́ о́чі на́ша от су́єтних і преле́стних веще́й земни́х, напра́ви же уми́ і ми́слі на́ша к зрі́нію красо́т боже́ственних, пренебе́сних і нетлі́нних, сердця́ на́ша неду́гующая страстьми́ гріхо́вними, ісціли́, да не прильпну́ть сласте́м привре́менним і безмі́стним; согрі́й же я боже́ственною любо́вію, да вожделі́ють і́стиннаго і непреходя́щаго блаже́нства, є́же в Бо́зі. Укріпи́ нас к ісполне́нію за́повідей Госпо́дніх, даждь нам покая́ніє серде́чноє і умиле́ніє сле́зноє, моли́тву непреста́нную і трудолю́біє неосла́бноє, бо́дренноє трезві́ніє ума́ і хране́ніє се́рдця, мир помисло́в, чистоту́ жела́ній, правоту́ дія́ній, да, ізба́вльшеся тобо́ю от всіх враг ви́димих і неви́димих, от вся́ких зол душе́вних і тіле́сних, і соблю́дше ві́ру пра́вую, наде́жду неотло́жную і любо́в нелицемі́рную, богоуго́дні сконча́єм житіє́ на́ше на землі́, і преше́дше в жизнь ві́чную, сподо́бимся зрі́ти трисві́тлую зарю́ трисія́ющаго ві́чнаго Со́лнця, і в невече́рнім дні Небе́снаго Ца́рствія, ку́пно с тобо́ю і со всі́ми святи́ми, благода́рні воспіва́ти і благословля́ти Пресвяту́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О богоблаже́нне і приснопа́м'ятне о́тче наш Анто́ніє, не мним тя ме́ртва су́ща, а́ще ті́лом і преста́вился єси́ от нас, но жив в собо́рі А́нгелов водворя́єшися. Моли́ за ни, ізбра́нниче Христо́в, і не пре́зри нас, ві́рою і любо́вію чту́щих тя, помина́й нас недосто́йних у Престо́ла Царя́ Небе́снаго, тебі́ бо даде́ся благода́ть моли́тися за ни. О засту́пниче і моли́твенниче наш до́брий! Се бо святи́х моще́й твої́х ра́ка, пред очи́ма на́шима ви́дима єсть, сохраня́й нас всегда́ от сіте́й вра́жиїх; моли́ся ко Го́споду о спасе́нії душ на́ших, і іспроси́ нам покая́нія вре́м'я і христия́нськую кончи́ну безболі́зненну, непости́дну, ми́рну, да невозбра́нно пре́йдем мита́рства возду́шних князе́й і сподо́бимся Небе́снаго Ца́рствія со всі́ми угоди́вшими Влади́ці Не́ба і землі́, Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О всеблаже́нне о́тче наш, преподо́бне Анто́ніє, те́плий засту́пниче і помо́щниче с ві́рою призива́ющим тя, ізба́ви нас моли́твами сі ко Го́споду от вся́каго обстоя́нія бісо́вськаго і ізми́ нас, окая́нних і недосто́йних рабо́в твої́х, о чудотво́рче Анто́ніє, от уст па́губнаго змі́я, зія́ющаго пожре́ти нас і свести́ во ад жи́вих, прості́ нас, о́тче, єли́ко согріши́хом ті, і істо́ргни нас от гріха́ і вся́кия напа́сти, приходя́щия гріхо́в ра́ди на́ших. Пода́ждь душа́м на́шим утіше́нія, всади́ в сердця́ на́ша страх Суда́ Бо́жия і ізба́ви нас от враго́в на́ших, ви́димих і неви́димих, тебі́ бо і́мами те́пла моли́твенника і засту́пника, і́же в біда́х су́щії і в гріхи́ впа́дшия. Ти бо яви́ся столп благоче́стія, воздержа́нія пра́вило, смиренному́дрія о́браз, цілому́дрія наста́вник, убо́гим і сирота́м засту́пник і храни́тель прибега́ющим к тебі́. Кто у́бо по досто́їнству мо́жеть похвали́ти равноа́нгельноє твоє́ житіє́ і кто мо́жеть ізчести́ твої́х трудо́в по́двизі і сле́зи ко Го́споду, воі́стинну я́ко со́лнця світлі́йши возсія́ша твоя́ ісправле́нія. Ревни́тель бо бисть всіх святи́х преподо́бних і пра́ведних і учи́тель духо́вний, побо́рник, і засту́пник, і моли́твенник, Пресвяті́й Тро́йце предстоя́. Ти я́ко мир оста́вил єси́ і я́же в ми́рі, і нас в покая́ніє приведи́ ко Го́споду моли́твами сі, о́тче всечестне́йший, да і ми сподо́бимся ві́чних благи́х, іді́же наслажда́єшися Небе́сния сла́ви жела́ємаго Ісу́са Христа́, І́стиннаго Бо́га на́шего і Сладча́йшаго Влади́ки і Го́спода всіх. Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Геннадію, Костромському і Любимоградському чудотворцю","e":"Prayer to St Gennadius, Wonderworker of Kostroma and Lyubimograd","secs":[{"h":"Тропар, глас 4","ps":["Я́ко пустиннолюби́вая го́рлиця, / от су́єтнаго і многом'яте́жнаго ми́ра в пусти́ню удали́вся, / чистото́ю і гові́нієм, моли́твами і тружде́нієм / просла́вил єси́ Бо́га в душе́ і тілесі́ своє́м. / І та́ко благоче́стно пожи́в, / яви́лся єси́, преподо́бне Генна́діє, пусти́ні Любимогра́дськия украше́ніє, / і́ноком честна́го житія́ о́браз / і те́плий моли́твенник за всіх, // притека́ющих к тебі́ с ві́рою."]},{"h":"Кондак, глас 3","ps":["Моли́твою і посто́м, тружде́нієм і терпі́нієм / умертви́вий вся́коє пло́ті мудрова́ніє, / чистоти́ сосу́д благолі́пен, / Боже́ственних даро́в і чуде́с прича́стник, / і́ноком же до́блій наста́вник бил єси́, / сподвиза́яся блаже́нному Корни́лію, о́тче Богому́дре. / Сего́ ра́ди вопіє́м: / моли́ся ко Го́споду, // да моли́твами твої́ми да́руєть мир і спасе́ніє душа́м на́шим."]},{"h":"Молитва","ps":["Ізбра́нниче Бо́жий і чудотво́рче, преподо́бний о́тче Генна́діє! От ю́ности твоєя́ іспо́лнен сий Ду́ха прему́дрости і ра́зума, Ду́ха благоче́стія і стра́ха Госпо́дня, і приї́м вся ору́жія Бо́жия, препоя́сав чре́сла твоя́ і́стиною, обо́лкся в броня́ пра́вди і обу́в но́зі во угото́ваніє благовіствова́нія ми́ра, над всі́ми же восприї́м щит ві́ри, возмо́гл єси́, я́ко добр во́їн Христо́в, вся стрі́ли лука́ваго разжже́нния угаси́ти. Сего́ ра́ди водворя́яся днесь с ли́ками Безпло́тних сил в оби́телях Отця́ Небе́снаго, неув'яда́ємим вінце́м ув'язе́н єси́ і, предстоя́ Престо́лу Царя́ сла́ви, Го́спода сил, і́маши дерзнове́ніє возноси́ти к Нему́ моле́нія і благохвале́нія твоя́. Ми же, окая́ннії, возводя́ із глубини́ зол о́чі і сердця́ на́ша ко Го́рнему Сіо́ну, Жили́щу Бо́га Іа́ковля, мо́лим тя, преподо́бне Генна́діє: бу́ди засту́пником і хода́таєм на́шим пред Бо́гом і Го́сподем на́шим, Судіє́ю пра́веднійшим, Єго́же ви́ну прогнівля́єм, согріша́юще пред Ним. І я́коже во дні пло́ті своєя́ ди́вная і пресла́вная соверши́л єси́, о́тче всехва́льне, та́ко і ни́ні, преше́д от нас в оби́телі Отця́ Небе́снаго, удиви́ хода́тайством свої́м ми́лость Госпо́дню на нас. Да, отбі́гше нече́стія і мирськи́х по́хотей, Бо́гові же благоугоди́вше, обря́щем по́мощ Єго́ во вре́м'я благопотре́бно і благослове́ніє на ни і на діла́ рук на́ших, і да сподо́бит нас наслі́дити Ца́рство Небе́сноє і с ли́ки святи́х сла́вити і воспіва́ти пречестно́є і великолі́поє і́м'я Отця́, і Си́на, і Свята́го Ду́ха ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Серафиму, архієпископу Богучарському","e":"Prayer to St Seraphim, Archbishop of Boguchar","secs":[{"h":"Тропар, глас 4","ps":["Боже́ственною ре́вностію при́сно распала́єм, / Правосла́вія столп яви́лся єси́ / в Софі́ї гра́де возсія́в, / і благоче́стієм твої́м мно́гия лю́ди ко Христу́ приве́л єси́, / па́стирю до́брий, святи́телю Серафи́ме, // моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 5","ps":["Сосу́д Боже́ственних даро́в / і дом Святи́я Тро́йці яви́лся єси́, / чудотво́рче святи́телю о́тче Серафи́ме, / ті́мже, імі́я дерзнове́ніє ко Го́споду, / не оста́ви нас си́рих, / і я́коже обіща́лся єси́, / іспроси́ нам моли́твами твої́ми // мир і ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Вознеси́йся на висоту́ смиренному́дрія, / благоче́стія учи́тель яви́лся єси́, / Правосла́вія побо́рниче і стра́нних предста́телю, / мона́шествующих похвало́ і па́стирю ізря́дний. / Ті́мже любо́вію зове́м ті: // ра́дуйся, Серафи́ме чудотво́рче."]},{"h":"Молитва","ps":["О чудотво́рче преди́вний, святи́телю о́тче Серафи́ме! Ти, єще́ жив сий, рекл єси́ ві́рним: я́ко а́ще улучу́ дерзнове́ніє у Го́спода, не оста́влю вас си́рих. Сего́ ра́ди, помина́юще глаго́ли твоя́ і діла́ милосе́рдія твоєго́ в жи́зні вре́менній, любо́вію припа́даєм і усе́рдно про́сим: моли́ся непреста́нно у Престо́ла Царя́ Сла́ви о всіх нас, бли́жніх і да́льних, при́сних і стра́нних, немощни́х і грі́шних, любо́вію почита́ющих тя. Ти от младе́нства благода́тію Бо́жиєю просвіще́н бил єси́, в ю́ності же ум соверше́нний стяжа́в, ю́ноши і ді́ви умудри́л єси́. Дости́гше же му́жеська во́зраста, усе́рдний ді́латель Боже́ственних доброді́телей яви́лся єси́. Сего́ ра́ди утверди́ і нас во благоугожде́нії Бо́гу і, я́ко па́стир до́брий, і́же ізря́дно о́вці Христо́ви упа́сл єси́, наста́ви нас на путь покая́нія. Я́ко світи́льник Сві́та І́стиннаго просвіти́ нас і сохрани́ от заблужде́ній і собла́знов ми́ра сего́, і я́ко чудотво́рець ди́вний не преста́й явля́ти ми́лость свою́ всім с любо́вію притека́ющим к тебі́. Па́стирю до́брий, не оста́ви па́ству, в зе́млях Бо́лгарськой і Українськой і і́нуді су́щую. Бу́ди ско́рий помо́щник призива́ющим тя от всіх конце́в землі́, да просла́виться неізрече́нноє милосе́рдіє Пастиренача́льника і Го́спода на́шего Ісу́са Христа́, при́сно прославля́ємаго і спокланя́ємаго со Безнача́льним Єго́ Отце́м, і Всесвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мученику Іоанну Воїну","e":"Prayer to the Martyr John the Warrior","secs":[{"h":"Тропар, глас 4","ps":["Всеблага́го Бо́га і Царя́ / благові́рний раб і во́їн яви́лся єси́, Іоа́нне чудоді́телю, / пострада́в бо ра́ди ві́ри му́жеськи, / блаже́нно же сконча́в тече́ніє, / зри́ши Всетворця́ Го́спода в Небесі́х світлі́йше. / От Него́же приє́м дарова́ніє чуде́с, / стра́ждущим челові́ком во вся́ких напа́стіх помога́єши, / укріпля́єши во́їни в ра́тіх, / от враго́в пліне́нія, ран же і внеза́пних смерте́й і от бід лю́тих ізима́єши. / Ті́мже моли́ Влади́ку Христа́, приснопа́м'ятне, / да во вся́ком обстоя́нії сотвори́ть нам ми́лость / і не введе́ть нас во іскуше́нія, // но спасе́ть ду́ші на́ша, я́ко Человіколю́бець."]},{"h":"Кондак, глас 6","ps":["Благочести́ваго во́їна Христо́ва, / побіди́вшаго враги́ душе́вния і тіле́сния богому́дренно, / Іоа́нна му́ченика достодо́лжно пі́сньми восхва́лим, / чудоді́йствуя бо, подає́ть оби́льная ісціле́нія стра́ждущим лю́дем / і мо́литься Го́споду Бо́гу // от вся́ких бід спасти́ правові́рния."]},{"h":"Молитва 1","ps":["О, му́чениче Христо́в, Іоа́нне во́їне! Хра́брий єси́ во бра́ніх, і враго́м прогони́тель, і оби́димим засту́пник, всім правосла́вним христия́ном. О, вели́кий засту́пниче і уго́дниче Христо́в, Іоа́нне вої́нственниче! Поми́луй нас, грі́шних і недосто́йних, і заступи́ в біда́х і в ско́рбіх, і в печа́ліх і во вся́кой злой напа́сти, і от вся́каго зла́го і оби́дящаго челові́ка, тебі́ бо дана́ бисть такова́я благода́ть от Бо́га, є́же моли́тися за ни, грі́шния, в біда́х і напа́стіх злі стра́ждущия. Ізба́ви у́бо нас от оби́дящих і ненави́дящих, бу́ди нам побо́рник крі́пок на вся ви́димия і неви́димия враги́ на́ша. О, вели́кий побо́рниче, Іоа́нне во́їне! Не забу́ди нас, всегда́ моля́щихся тебі́, прося́щих по́мощі і неоску́дния ми́лости твоєя́, і сподо́би нас, грі́шних і недосто́йних, получи́ти от Бо́га неізрече́нная блага́я, я́же угото́ва лю́б'ящим Єго́. Я́ко подоба́єть Єму́ вся́кая сла́ва, честь і поклоне́ніє, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва 2","ps":["О, му́чениче Христо́в Іоа́нне Во́їне! Хра́брий во бра́ніх, і ско́рий засту́пник правосла́вних христия́н в біда́х і напа́стях їх, по да́нной благода́ті от Бо́га! Бу́ди нам побо́рник крі́пок на вся ви́димия і неви́димия враги́ на́ша. Во́їнству на́шему на враги́ побі́ду да́руй, да смиря́ться проти́в'ящіїся нам і вразум'я́ться, і Бо́га і́стиннаго позна́ють і Святу́ю Єго́ Це́рков Правосла́вную. Ми же, грі́шнії, да сподо́бимся прославля́ти Го́спода Спа́са на́шего во Ца́рствії Єго́ вку́пі с тобо́ю во ві́ки. Амі́нь."]},{"h":"Молитва 3","ps":["О, вели́кий Христо́в му́чениче Іоа́нне, правосла́вних побо́рниче, враго́в прогони́телю і оби́димих засту́пниче! Усли́ши нас, в біда́х і ско́рбіх моля́щихся тебі́, я́ко дана́ тебі́ бисть благода́ть от Бо́га печа́льния утіша́ти, немощни́м помога́ти, непови́нния от напра́сния сме́рті ізбавля́ти і за всіх злі стра́ждущих моли́тися. Бу́ди у́бо і нам побо́рник крі́пок на вся ви́димия і неви́димия враги́ на́ша, я́ко да твоє́ю по́мощію і побо́рством по нас посрам'я́ться всі явля́ющії нам зла́я. Умоли́ Го́спода на́шего, да сподо́бит ни, грі́шния і недосто́йния раби́ Своя́ (імена́), получи́ти от Него́ неізрече́нная блага́я, я́же угото́ва лю́б'ящим Єго́, в Тро́йці Святі́й сла́вимаго Бо́га, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Особисте прохання","ps":["О, вели́кий Христо́в му́чениче Іоа́нне! Усли́ши м'я, прибега́ющего к тебі́ (і́м'я), пода́ждь в ско́рбі моє́й ско́рую по́мощ і заступле́ніє (содержа́ніє проше́нія), я́ко да твоє́ю по́мощію і побо́рством по мні посрам'я́ться всі явля́ющії мні зла́я. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Серафиму, Вирицькому чудотворцю","e":"Prayer to St Seraphim of Vyritsa, the Wonderworker","secs":[{"h":"Тропар, глас 4","ps":["Я́ко пресві́тлая звізда́ Українськия землі́, / возсія́л єси́ во ві́си Ви́рицтей, / преподо́бне Серафи́ме, / і благода́тію Свята́го Ду́ха наставля́єм, / сві́том чуде́с твої́х страну́ на́шу озари́л єси́. / Ті́мже ко гро́бу твоєму́ притека́юще, уми́льно глаго́лем: // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["Я́ко вели́каго моли́твенника за зе́млю на́шу / і уті́шителя те́плаго притека́ющих к тебі́, / ублажа́єм тя, втори́й український о́тче Серафи́ме, / вся бо я́же в ми́рі кра́сная оста́вил єси́, / всім се́рдцем устреми́лся єси́ к черто́гам сладча́йшаго Христа́ / і в годи́ну лю́тих гоне́ній о́браз кро́тости і смире́нія всім бил єси́: / не преста́й і ни́ні моли́тися за ни, / да в терпі́нії обря́щем путь покая́нія // і с тобо́ю ви́ну сла́вим Пресвяту́ю Тро́йцю."]},{"h":"Інший тропар, глас 8","ps":["Крест приї́м свой, преподо́бне, ра́дуяся, / неразде́льним по́мислом послі́довал єси́ Христу́, / бил купе́ць єси́ воі́стину пресла́вний, / я́ко не земно́є, но Небе́сноє сокро́вище стяжа́ / сего́ ра́ди спасе́ся тобо́ю мно́зі ча́да твоя́, ї́хже возлюби́л єси́. / І ни́ні, о́тче наш Серафи́ме, моли́ся // покая́ніє нам дарова́ти і в ра́зум і́стини прийти́."]},{"h":"Інший тропар, глас 3","ps":["Купе́ць вели́к соді́лался єси́, / преподо́бне о́тче Серафи́ме, / сий в ми́рі, к мно́гому бога́тству тлі́нному / ти ніколи́же се́рдця прилага́л єси́, / послу́шник і́стинен / і доброді́телей подви́жник, / єгда́ же, вся оста́вль, / на крест мона́шества восше́л єси́, / да́ри Свята́го Ду́ха мно́гі тебі́ да́шася / і я́ко єди́наго от дре́вніх тя яви́ша / проро́ка, ста́рця, / чудотво́рця і моли́твенника, / столпа́ подви́жником, спасе́нія вождя́. / Сего́ ра́ди мо́лим тя: // і нас прему́дро ко спасе́нію упра́ви."]},{"h":"Кондак, глас 5","ps":["Дре́внім отце́м подража́я, / по́двигом до́брим подвиза́лся єси́ / і, благода́ть Ду́ха Свята́го оби́льно стяжа́в, / Саро́вському уго́днику уподо́бился єси́ / і мно́гим путь спасе́нія яви́л єси́. / Сего́ ра́ди зове́м ті: / ра́дуйся, преподо́бне Серафи́ме, / Алекса́ндро-Не́вския ла́ври ди́вний подви́жниче // і Ви́рицькия ві́си сла́вная похвало́."]},{"h":"Інший кондак, глас 5","ps":["Подража́я богоно́сному уго́днику Саро́вському, / Ду́ха Свята́го благода́ть оби́льно стяжа́л єси́: / Алекса́ндро-Не́вския ла́ври кри́не благоуха́нний, / Ви́рицькия ві́си похвало́, / сего́ ра́ди і ми тебі́ зове́м: / ра́дуйся, преподо́бне Серафи́ме, // ми́лостивий наш предста́телю пред Го́сподем."]},{"h":"Інший кондак, глас 3","ps":["Возра́дуйся па́ки, гра́де свята́го Петра́, / і ма́лая ві́сі Ви́риця, возвели́чися, / се бо світи́льник ві́ри в тебі́ просіява́єть, / всеїсцеля́ющий бальза́м нам істоча́ється, / новоявле́нний бо вели́кий чудотво́рець, / любве́ і покая́нія наста́вник, / проро́к і ста́рець, // но́вий преподо́бний Серафи́м в тебі́ явля́ється."]},{"h":"Інший кондак, глас 5","ps":["Уподо́бился єси́ дре́внім отце́м / і по́двигом до́брим подвиза́лся єси́, / благода́тію Христо́вою просвіти́вся, / от Него́же приє́м дарова́нія чуде́с, / неду́гующих ісціля́ти, / печа́льних і скорб'я́щих утіша́ти, / оби́димих і гони́мих защища́ти / і всім в ну́ждах су́щим отра́ду / і ско́роє ізбавле́ніє подава́ти. / Сего́ ра́ди, я́ко вели́каго чудотво́рця чту́ще, / мо́лим тя, ча́да твоя́, преподо́бне Серафи́ме: // от всіх бід ізба́ви нас моли́твами твої́ми."]},{"h":"Молитва","ps":["О богоблаже́нний і премилосе́рдий о́тче наш Серафи́ме! Ві́дуще тя і по сме́рті я́ко жи́ва су́ща, с ві́рою припа́даєм ті і вопіє́м: не забу́ди убо́гих твої́х до конця́, но ми́лостивно при́зри на ста́до твоє́ духо́вноє і упаси́ є, до́брий па́стирю, благоприя́тними твої́ми к Бо́гу моли́твами. Іспроси́ нам от Го́спода вре́м'я на покая́ніє і гріхо́вния жи́зні ісправле́ніє, ві́си бо вся не́мощі на́ша душе́вния: не і́мами діл ві́ри і спасе́нія, не і́мами ре́вности ко і́стинному богоугожде́нію, плени́хомся умо́м в поги́бельних страстеіх, растле́хом сердца́ во гну́сних по́хотіх. Что у́бо ча́єм, і на что наді́ємся неключи́мії, разори́вше хра́мини душ на́ших; Єй, святи́й о́тче, простри́ моли́твенно ру́ці твої́ ко Го́споду і умоли́ Спаси́теля ро́да челові́чеськаго косну́тися благода́тію окамене́лих серде́ць на́ших, оми́ти нас слеза́ми покая́нія, возста́вити во ві́рі, укріпи́ти во благоче́стії і вся поле́зная ко спасе́нію дарова́ти. Не посрами́ упова́нія на́шего, є́же по Бо́зі і Богоро́дице на тя возлага́єм, но бу́ди нам ско́рий помо́щник, уті́шитель в ско́рбіх і покрови́тель во обстоя́ніїх, да сподо́бимся моли́твами твої́ми наслі́довати Ца́рствіє Небе́сноє, іді́же всі святі́ї непреста́нно сла́в'ять і воспіва́ють пречестно́є і великолі́поє і́м'я Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Пимену, архімандриту Угрешському","e":"Prayer to St Pimen, Archimandrite of Ugresha","secs":[{"h":"Тропар, глас 2","ps":["Мона́шеськоє житіє́ от ю́ности возлюби́в, / во оби́тель Угре́шськую всели́лся єси́, / іді́же труди́ ко трудо́м прилага́я, / мона́хов мно́жество собра́л єси́, / ї́хже сердца́ согріва́я і тяготи́ нося́, / путе́м Христо́вим ше́ствовал єси́. / Пи́мене преподо́бне, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 1","ps":["Тобо́ю, преподо́бне о́тче Пи́мене, / оби́тель Угре́шськая благослове́нієм Бо́жиїм процві́тшая, / па́м'ять твою́ ни́ні пра́зднуєть / і лику́ющи зове́ть ті; / сла́ва Да́вшему тебі́ крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Пи́мене! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́; не премолчи́ за ни ко Го́споду і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних, у престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу; і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва; а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с небе́сними си́лами, у престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу о по́льзі душ на́ших і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чной му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Далмату Ісетському","e":"Prayer to St Dalmatus of Isetsk","secs":[{"h":"Тропар, глас 2","ps":["Ди́вний і сла́вний уго́дниче Христо́в, / сла́ви і по́честей вся́чеських бі́гая, / в пусти́ні Ісе́тськой всели́лся єси́, / созида́я в моли́твах оби́тель твою́, а́ки сті́ни Ієрусали́мськія, / засту́пничеством Цари́ці Небе́сния чу́десно обрі́л єси́, / стра́хом Бо́жиїм к стопа́м твої́м поверга́я би́вшаго врага́ // і внов воздви́гни сердця́ на́ша, отступле́нієм оскверне́нния."]},{"h":"Інший тропар, глас 4","ps":["По́двигом до́брим подвиза́вся, / посто́м, бді́нієм моли́твою і любо́в Христо́ву стяжа́л єси́, / чу́дним же заступле́нієм Бо́жия Ма́тере / угро́зи неві́рних ні во что же вміни́в, / я́ко світи́ло на тве́рди Небе́сній просія́л єси́, / преподо́бне о́тче наш Далма́те, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Моли́твами і ві́рою оби́тель свою́ огради́вий, / зе́млю Ісе́тськую ізря́дно преобрази́вий, / блаже́нним успе́нієм честно́є ста́рчество запечатлі́вий, / явле́нієм моще́й твої́х нас не оста́вивий, / о́тче наш преподо́бне Далма́те, // і ни́ні предста́ни і заступи́ чту́щих святу́ю па́м'ять твою́."]},{"h":"Інший кондак, глас 4","ps":["От ю́ности Христа́ возлюби́вше, / су́єтная мирська́я і мудрова́нія презрі́л єси́, / му́жеськи же в пусти́ню всели́вшеся, / вся напа́сти вра́жия побіди́л єси́ / до́брий і во́їн Христо́в яви́лся єси́. / Помина́й нас, ві́рою чту́щих тя, // Далма́те преблаже́нне."]},{"h":"Молитва","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Далма́те! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас недосто́йних у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу: і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка (іко́на твоя́ свята́я) пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с Небе́сними Си́лами, у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на Не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Максиму Греку","e":"Prayer to St Maximus the Greek","secs":[{"h":"Тропар, глас 8","ps":["Заре́ю Ду́ха облиста́єм, / вити́йствующих богому́дренно сподо́бился єси́ разумі́нія, / неві́дінієм омраче́нная сердца́ челові́ков сві́том благоче́стія просвіща́я, / пресві́тел яви́лся єси́ правосла́вія світи́льник, Макси́ме преподо́бне, / отону́дуже ре́вности ра́ди Всеви́дящаго, / оте́чества чужд і стра́нен, Українськия страни́ бил єси́ пресе́льник, / страда́нія темни́ць і заточе́нія от самодержа́внаго претерпі́в, / десни́цею Ви́шняго вінча́єшися і чудоді́йствуєши пресла́вная. / І о нас хода́тай бу́ди непрело́жен, // чту́щих любо́вію святу́ю па́м'ять твою́."]},{"h":"Кондак, глас 8","ps":["Богодухнове́нним Писа́нієм і богосло́вія пропові́данієм / неві́рствующих суєму́дріє обличи́л єси́, всебога́те, / па́че же в Правосла́вії ісправля́я, на стезю́ і́стиннаго позна́нія наста́вил єси́, / я́коже свирі́ль богогла́сная, услажда́я сли́шащих ра́зуми, / непреста́нно весели́ши, Макси́ме досточу́дне. / Сего́ ра́ди мо́лим тя: моли́ Христа́ Бо́га / гріхо́в оставле́ніє низпосла́ти // ві́рою пою́щим всесвято́є твоє́ успе́ніє, Макси́ме, о́тче наш."]},{"h":"Молитва","ps":["Преподо́бне о́тче Макси́ме! Воззри́ на нас ми́лостивно і к землі́ приве́рженних возведи́ к висоті́ небе́сній. Ти го́ре на небесі́, ми на землі́ ни́зу, удалени́ от тебе́, не толи́ко мі́стом, єли́ко гріхми́ свої́ми і беззако́нії, но к тебі́ прибіга́єм і взива́єм: наста́ви нас ходи́ти путе́м твої́м, вразуми́ і руково́дствуй. Вся твоя́ свята́я жизнь бисть зерца́лом вся́кия доброді́телі. Не преста́ни, уго́дниче Бо́жий, о нас вопія́ ко Го́споду. Іспроси́ предста́тельством свої́м у Всеми́лостиваго Бо́га на́шего мир Це́ркві Єго́, под зна́менієм креста́ во́їнствующей, согла́сіє во ві́рі і єдиному́дріє, суєму́дрія же і раско́лов істребле́ніє, утвержде́ніє во благи́х ді́ліх, больни́м ісціле́ніє, печа́льним утіше́ніє, оби́женним заступле́ніє, бе́дствующим по́мощ. Не посрами́ нас, к тебі́ с ві́рою притека́ющих. Всі правосла́внії христия́не, твої́ми чудеси́ іспо́лненнії і ми́лостьми облагоде́тельствованнії, іспові́дують тя би́ти своєго́ покрови́теля і засту́пника. Яви́ дре́внія ми́лості твоя́, і ї́хже отце́м всепомоществова́л єси́, не отри́ни і нас, чад їх, стопа́ми їх к тебі́ ше́ствующих. Предстоя́ще всечестні́й іко́ні твоє́й, я́ко тебі́ жи́ву су́щу, припа́даєм і мо́лимся: прийми́ моле́нія на́ша і вознеси́ їх на же́ртвенник благоутро́бія Бо́жия, да при́ймем тобо́ю благода́ть і благовре́менную в ну́ждіх на́ших по́мощ. Укріпи́ на́ше малоду́шіє і утверди́ нас во ві́рі, да несомні́нно упова́єм получи́ти вся блага́я от благосе́рдія Влади́ки моли́твами твої́ми. О, превели́кий уго́дниче Бо́жий! Всім нам, с ві́рою притека́ющим к тебі́, помози́ предста́тельством твої́м ко Го́споду, і всіх нас упра́ви в ми́рі і покая́нії сконча́ти живо́т наш і пресели́тися со упова́нієм в блаже́нния ні́дра Авраа́мова, іді́же ти ра́достно во труді́х і по́двизіх ни́ні почива́єши, прославля́я со всі́ми святи́ми Бо́га, в Тро́йці сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Макси́ме, не забу́ди убо́гих свої́х до конця́, но помина́й нас во святи́х свої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до своє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад свої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти своя́ духо́вния, я́ко імі́я дерзнове́ніє к Небе́сному Царю́, не премолчи́ за ни ко Го́споду і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних у престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо і ті́лом преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх, і вся́кия пре́лести бісо́вськия, і ко́зней дия́вольських, па́стирю наш до́брий; а́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с Небе́сними си́лами, у Престо́ла Вседержи́теля предстоя́щи, досто́йно весели́ться. Ві́дуще бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на Не́бо, от мита́рств же го́рких, бісо́в, возду́шних князе́й і от ві́чния му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і с Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, прему́дрости сокро́вищнице, вся́каго ві́дінія і разумі́нія іспо́лненная, Ду́ха Свята́го неумо́лчний орга́не, трубо́ Боже́ственная, возвіща́ющая нам велі́нія Зако́на Бо́жия, о́тче пресла́вне Макси́ме! Се ни́ні ми припа́даєм ті, о́тче блаже́нне, і вопіє́м усе́рдно: просвіти́ омраче́нния уми́ на́ша, неве́дущия велі́ній Бо́жиїх, і напра́ви ду́ші на́ша во є́же ді́лати за́повіді Госпо́дні прилі́жно і в словесі́х Бо́жиїх поуча́тися день і нощ. Огради́ уста́ на́ша от глаго́лов су́єтних, рече́ній лука́вих і многоглаго́ланія суєтного, і́мже ми приліпи́хомся па́че не́же словесе́м оправда́ній Бо́жиїх і возлюби́хом їх преви́ше звяця́нія псалти́ри і гу́слей Дави́дових. Укріпи́ язи́ки на́ша, во є́же істоча́ти їм глаго́ли спасе́нія, пі́сні моли́твенния і словеса́ псало́мськая, і́миже подоба́єть Го́спода воспіва́ти і превозноси́ти Єго́ до́ндеже єсьми́. Ти, о́тче преподо́бне, і в те́мности узи́лища, му́чим непра́ведно от приста́вник неми́лостивих, во сві́ті повелі́ній Госпо́дніх пребива́ше і світлостьми́ Єго́ ісполня́ше ум свой і помишле́ніє своє́. Ми же, ліни́вії і нетерпіли́вії, світ со́лнечний на всяк день зря́ще і глаго́ли Свята́го Писа́нія во ушесі́х свої́х іму́ще, ні о внима́нії глаго́лам єва́нгельським, ніже́ о науче́нії в наставле́ніїх оте́чеських попече́нія возиме́хом. При́зри на ни, а́лчущия пи́щі духо́вния, оба́че не приступа́ющия к трапе́зі Прему́дрости Бо́жия; даждь нам растворе́нноє в ча́ші Єя́ вино́ і хліб, сходя́й от рук Бо́жиїх с Небесе́, да і ми іспо́лнимся ві́дінія за́повідей Госпо́дніх і разумі́нія, что єсть пра́во слі́довати стопа́м Бо́жиїм; іспроси́ нам благослове́ніє Госпо́днє, науча́ющеє оправда́нієм Єго́, і приведи́ ни с собо́ю пред Лице́ Бо́жиє, Єму́же ти предстоя́л єси́ при́сно, я́коже і пре́жде просія́вшії святі́ї му́жи і жени́, да тобо́ю вразумле́ннії і наста́вленнії, путі́ своя́ іспра́вивше, удосто́їмся вни́ти в безконе́чную сві́тлость Небе́снаго Ца́рствія, іді́же ку́пно с ли́ки святи́х і со́нми Безпло́тних сподо́бимся при́сно воспіва́ти Отця́, Си́на і Пресвята́го Уті́шителя Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомученику Феодору Стратилату","e":"Prayer to the Great Martyr Theodore Stratelates","secs":[{"h":"Тропар, глас 4","ps":["Воїнствосло́вієм і́стинним, страстоте́рпче, / Небе́снаго Царя́ воєво́да предо́брий бил єси́, Фео́доре: / ору́жіями бо ві́ри ополчи́лся єси́ му́дренно / і побіди́л єси́ де́монов полки́, / і побідоно́сний яви́лся єси́ страда́лець. / Ті́мже тя ві́рою // при́сно ублажа́єм."]},{"h":"Кондак, глас 2","ps":["Му́жеством душі́ во ві́ру оболки́йся, / і глаго́л Бо́жий а́ки копіє́ в ру́ку взем, врага́ побіди́л єси́, / му́чеников преве́лій Фео́доре, // с ни́ми Христу́ Бо́гу моля́ся не преста́й о всіх нас."]},{"h":"Молитва","ps":["О святи́й, сла́вний і всехва́льний великому́чениче Фео́доре Стратила́те! Мо́лим тя пред іко́ною твоє́ю свято́ю: моли́ с на́ми і о нас, раб Бо́жиїх (імена́), умоля́ємаго от Своєго́ благосе́рдія Бо́га, да ми́лостивно усли́шить нас, благости́ні у Него́ прося́щих, і вся на́ша ко спасе́нію і житію́ ну́жная проше́нія да іспо́лнить. Єще́ же мо́лим тя, святи́й побідоно́сче Фео́доре Стратила́те, разруши́ си́ли возстаю́щих на ни враго́в, ви́димих і неви́димих. Умоли́ же Го́спода Бо́га, всея́ тва́рі Созда́теля, ізба́вити нас от ві́чнаго муче́нія, да всегда́ прославля́єм Отця́ і Си́на і Свята́го Ду́ха і твоє́ іспові́дуєм предста́тельство, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Варлааму Керетському","e":"Prayer to St Barlaam of Keret","secs":[{"h":"Тропар, глас 1","ps":["Боже́ственною сви́ше просвіти́вся благода́тію, преподо́бне, / мир оста́вил єси́, / жите́йськую печа́ль і всяк м'яте́ж ми́ра сего́ / любве́ ра́ди Христо́ви со дерзнове́нієм отве́ргл єси́, / єва́нгельськи Христу́ послі́довал єси́, / і, Того́ яре́м взем, во всем во́лі Єго́ повину́лся єси́, / і весь ра́зум і се́рдце к Нему́ неукло́нно возложи́л єси́, / Христа́ ра́ди ті́ло своє́ ізнуря́я посто́м і бді́нієм, в моли́твах свої́х не усипа́я, / Бо́га ми́лостива творя́ і Пречи́стую Богоро́дицю Моле́бницю предлага́я, / і сего́ ра́ди от Бо́га восприє́м власть і си́лу на сопроти́внаго врага́, / не убоя́ся возду́шния і морськи́я тяготи́ і сту́дені, ніже́ уклони́ся, / і морсько́ю пучи́ною в ма́лі ладі́їце по вода́м ше́ствіє творя́, / про́тив зі́льнаго обурева́нія пла́ваше, / промишле́нієм Боже́ственнаго ра́зума направля́єм, / і о́коло Свята́го Но́са непроходи́мий путь морськи́й / от ядови́таго че́рвія / благопрохо́ден челові́ком без вреда́ сотвори́л єси́ моли́твами свої́ми, / і мно́гим терпі́нієм во вре́менній жи́зні по́двиг соверши́л єси́, / і, равноа́нгельноє житіє́ пожи́в, / ті́мже і по преставле́нії істоча́єши чуде́с благода́ть / і́же ві́рою приходя́щим к тебі́, Варлаа́ме, преблаже́нне о́тче наш, / вопіє́м ті: моли́ Христа́ Бо́га, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Все у́мноє своє́ жела́ніє к Бо́гу впери́в, / і Тому́ невозвра́тно от душі́ послі́довал єси́, / і жите́йськія молви́ отри́нув, / в моли́твах, і слеза́х, і злострада́ніїх плоть свою́ ізнуря́я, / до́брі подвиза́вся проти́ву неви́димаго врага́ ко́знем, / і, побіди́в я, веселя́ся, преше́л єси́ к Небе́сним черто́гом, / і ни́ні со А́нгели Святі́й Тро́йці предстоя́, / отню́ду же і Всеви́дящеє о́ко, твоя́ труди́ ви́дів, / да́ром чуде́с по преставле́нії обогати́ло тя єсть, / і́же тебі́ с ві́рою почита́ющим / ісціле́ніє подава́єши неви́димо / і мо́лишися непреста́нно, сохраня́я оте́чество своє́ і лю́ди / от враг ви́димих і неви́димих ненаві́тни, / да всі тебі́ вопіє́м: / преподо́бне о́тче наш Варлаа́ме, // моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О, преподо́бне о́тче наш Варлаа́ме, я́ко імі́яй дерзнове́ніє ко Творцю́, Ізба́вителю всіх, І́же в Тро́йці Святі́й покланя́ємому і́стинному Христу́, Бо́гу на́шему, пом'яни́ нас в моли́твах свої́х і всіх нас моле́нія, Бо́гу возсила́ємая, прийми́ і принеси́ хода́тайственні. Мо́лим тя, ізба́ви нас от напа́стей, і на мо́рі зі́льнаго обурева́нія, і потопле́нія морська́го невреди́ми сохрани́, і от всіх ви́димих і неви́димих враг ненаві́тни соблюди́, я́ко да твої́ми моли́твами, свя́те, согріше́ній на́ших оставле́ніє полу́чим і ві́чних благ сподо́бимся благода́тію і человіколю́бієм Го́спода на́шего Ісу́са Христа́, Єму́же сла́ва со Отце́м і Святи́м Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Соборові Кримських святих","e":"Prayer to the Synaxis of the Saints of Crimea","secs":[{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється Це́рков Кри́мская / і ра́достно торжеству́ють правосла́вних мно́жества, / соверша́я па́м'ять Таври́ческих всіх святи́х, / от апо́стол Христо́вих до ни́ні просла́вленних, / с ни́ми же новому́чеников і іспові́дников ві́ка двадца́таго, / ї́хже предста́тельством і моли́твами / да́руй, Го́споди, всім нам по́мощ Боже́ственную / непоколеби́ми пребива́ти в Правосла́вії, // Твою́ бога́тую ми́лость, благоде́нствіє і спасе́ніє душ на́ших."]},{"h":"Кондак, глас 3","ps":["Я́ко же́ртву непоро́чну і благоуго́дну Христу́ принося́ще, / Правосла́вная Це́рков Кри́мская сві́тло пра́зднуєть, / соверша́юще собо́рную па́м'ять святи́х уго́дников Таври́чеських, / от землі́ на́шея восте́кших / і насе́льниками ра́йських селе́ній би́вших. / І ми всі под кров їх моле́ній притека́ющи, / ізбавля́ємся от належа́щих бід і зол, / воспіва́я ку́пно с ни́ми Святу́ю Тро́йцю, // да́рующую нам спасе́ніє і ве́лію ми́лость."]},{"h":"Молитва","ps":["О, преблаже́ннії і пресла́внії му́ченици і іспові́дниці Таври́честії, Це́ркві Христо́вой досто́йноє украше́ніє, ско́рії засту́пниці і те́плії пред Го́сподем предста́теліє і моли́твенниці, зе́млю на́шу житіє́м, по́двигом і кро́вію освяти́вшії, священному́чениче Порфи́ріє, архіпа́стирю Кри́мський, і священнослужи́теліє, во у́зах да́же до сме́рти і́м'я Христо́во іспові́давшії Дими́тріє, Нико́лає, Варфоломе́є, Тимофе́є, Іоа́нне, Влади́мире, Анто́ніє, Нико́лає, Андре́є, Єлеяза́ре і му́ченици Дими́тріє і Стефа́не воззрі́те ми́лостивно на ни, чту́щих пресві́тлую па́м'ять ва́шу. Ви бо ревни́теліє єди́нства Це́ркві би́ли єсте́ і ни́ні на́шу зе́млю во святі́м правосла́вії утверді́те, от раско́лов і шата́ній огради́те, враго́в, ополча́ющихся на ни, ви́димих і неви́димих, низложі́те. Іспросі́те Человіколюби́ваго Бо́га дарова́ти нам ти́хоє і безм'яте́жноє житіє́ да сподо́бимся моли́твами ва́шими получи́ти оставле́ніє гріхо́в і дости́гнути Ца́рства Небе́снаго, і́де же ви непреста́нно сла́віте Всесвяту́ю Тро́йцю Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["O, всечестни́й собо́ре всеблаже́нних святи́х сородичей на́ших, всі святі́ї в землі́ Тавричестей подвизавшієся! Богоно́снії отці́, па́стиріє і учи́теліє, по́стници і іспові́дниці, новому́ченици і всі пра́веднії, по Богоро́дице на́ші предста́теліє пред Го́сподем! Ублажа́єм ва́ше свято́є житіє́, світи́льници Боже́ственнії, зві́зди сві́том ві́ри і доброді́телі светящієся і на́ша уми́ і се́рдця богому́дренне озаря́ющия, всю же вселе́нную висо́ких доброді́телей світлостьми́ удивившия і всю Тавричеськую зе́млю сві́том Єва́нгелія Христо́ва просветившия.","Приймі́те похва́льная словеса́ сія́, на́ша к вам усе́рдния моли́тви і колінопреклоне́нія, я́же вам прино́сим. Сві́тлоє празднетство в честь і па́м'ять ва́шу соверша́ємоє на́ми, обимі́те я́ко воню́ благоуха́нія і же́ртву благоприя́тну. Умоля́єм ва́шу богоподража́тельную любо́в, предста́теліє на́ша і покрови́теліє: сохрані́те вся гра́ди і ве́сі землі́ Кримськия от огня́, трясе́нія і бу́рних ві́тров, от гла́да, наше́ствія іноплеме́нников і междуусо́бния бра́ні. Оградите́ нас от вся́каго зла і посіті́те нас в не́мощіх на́ших.","Моли́твами ва́шими утверді́те Правосла́віє Це́ркві Кримськия і сохрані́те слове́сноє ста́до своє́ во ві́рі і доброді́телі. В терпі́нії і по́двизіх са́мі пожи́вшії, оградите́ і нас от пре́лести ми́ра сего́ лука́ваго, да отве́ргшеся себе́ і взе́мше крест, послі́дуєм Христу́. Пом'яні́те нас у Престо́ла Вседержи́теля Бо́га, Єму́ же предстоя́ще і со а́нгели ликовству́юще, мо́жете і нам, напа́тствуємим, помощі́, да безбі́дно препли́вше жите́йськую пучи́ну і невреди́мо соблю́дше сокро́вище ві́ри, приста́нища ві́чнаго спасе́нія дости́гнем, сла́в'яще ку́пно с ва́ми Отця́ і Си́на і Свята́го Ду́ха в безконе́чния ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва святим праотцям Адаму та Єві","e":"Prayer to the Holy Forefathers Adam and Eve","secs":[{"ps":["К вам, прароди́телем на́шим, о Ада́мі і Є́во, прибіга́єм ми, немощна́я ча́да ва́ша. Воззрі́те ми́лостивно на нас с висоти́ небе́сния ва́шея сла́ви і бу́діте нам помо́щници во іскуше́ніях і собла́зніх, от врага́ ро́да челові́чеськаго нам прибива́ющих. А́ще і соблазни́лися єсте́ дре́вле льсти́вними глаго́ли змі́євими і лиши́лися рая́ сла́дости, преби́сте оба́че оста́ток земни́я жи́зні ва́шея в покая́нії і сокруше́нії о неразу́мії своє́м, і та́ко снидо́сте во оби́телі печа́лі. В послі́док же дній приї́де Обетова́нний, є́же сокруши́ти держа́ву кня́зя ми́ра сего́. Пред спаси́тельними же страда́ньми Свої́ми предпосла́ ко отше́дшим живота́ сего́ пропові́дника покая́нія, і́же бисть предте́ча Єго́ на землі́ і в преіспо́дніх землі́. Ви же с ра́достію послу́шасте слове́с сего́, разуміва́юще, я́ко о Сі́мені ва́шем глаго́леть. По ма́лі же вре́мене потрясе́ся ад і огорчи́ся, сни́де бо Разруши́тель а́да. Огорчи́ся ад, і́бо упраздни́ся, огорчи́ся, і́бо пору́ган бисть, огорчи́ся, і́бо умертви́ся, огорчи́ся, і́бо связа́ся. Ви же возвесели́стеся і взигра́сте ду́хом, зря́ще Іскупи́теля ва́шего, по пло́ті от вас проісше́дшаго, Бо́га же су́ща безнача́льна і Отцю́ соприсносу́щна. Си́це у́бо і нас сподо́біте земно́є сіє́ і многоско́рбноє житіє́ в покая́нії прейти́, в бу́дущей же жи́зні зрі́ти ви́ну Спаси́теля душ на́ших і Го́спода на́шего Ісу́са Христа́, Єму́же со Отце́м і Ду́хом подоба́єть честь і поклоне́ніє ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Нилу Сорському","e":"Prayer to St Nilus of Sora","secs":[{"h":"Тропар, глас 4","ps":["Удали́вся бі́гая, дави́дськи, ми́ра, / і вся, я́же в нем, я́ко уме́ти, вміни́в, / і, в мі́сті безмо́лвні всели́вся, / духо́вния ра́дости іспо́лнился єси́, о́тче наш Ни́ле, / і, єди́ному Бо́гу ізво́лив служи́ти, / процві́л єси́, я́ко фі́нікс, / і, я́ко лоза́ благопло́дна, / умно́жил єси́ ча́да пусти́ні. / Тім благода́рственно вопіє́м: / сла́ва Укрі́пльшему тя в по́двигі пустинножи́тельства; / сла́ва Ізбра́вшему тя в Україні отше́льником уставополо́жника ізря́дна; // сла́ва моли́твами твої́ми і нас Спаса́ющему."]},{"h":"Кондак, глас 8","ps":["Любве́ ра́ди Христо́ви удали́вся мирськи́х смуще́ній, / ра́достною душе́ю всели́лся єси́ в пусти́ні, / в не́йже подвиза́вся до́брі, / я́ко А́нгел на землі́, о́тче Ни́ле, пожи́л єси́: / бді́нієм бо і посто́м ті́ло своє́ ізнури́л єси́ ві́чния ра́ди жи́зні. / Єя́же ни́ні сподо́бився, / во сві́ті неізрече́нния ра́дости Пресвяті́й Тро́йце со святи́ми предстоя́, / моли́, мо́лимтися, припа́дающе, ча́да твоя́, / сохрани́тися нам от вся́каго наві́та і злих обстоя́ній / ви́димих і неви́димих враг // і спасти́ся душа́м на́шим."]},{"h":"Молитва","ps":["О, преподо́бне і Богоблаже́нне о́тче Ни́ле, Богому́дрий наста́вниче і учи́телю наш! Ти любве́ ра́ди Бо́жия от мирськи́х смуще́ній удаля́яся, в непрохо́дній пусти́ні і в де́бріх всели́тися ізво́лил єси́, і я́ко лоза́ благопло́дна, ча́да пусти́ні умно́жив, сло́вом, писа́нієм і житіє́м о́браз вся́кия і́ночеськия доброді́телі яви́лся єси́; і я́ко а́нгел во пло́ті пожи́в на землі́, ни́ні в селе́ніїх Небе́сних, іді́же пра́зднующих глас непреста́нний, водворя́єшися, і с ли́ки святи́х Бо́гу предстоя́, Тому́ хвали́ і славосло́вія непреста́нно прино́сиши. Мо́лим тя, Богоблаже́нне, наста́ви і нас, под кро́вом твої́м жи́тельствующих, непреткнове́нно по стопа́м твої́м ходи́ти і Го́спода Бо́га всім се́рдцем свої́м люби́ти, Того́ єди́наго вожделі́ти і о Том єди́ном помишля́ти, му́жественно же і благоїску́сно проти́ву до́лу влеку́щих по́мислов і прило́гов вра́жиїх пра́тися і ти́я всегда́ побіжда́ти; вся́кую же тісноту́ мона́шеськаго житія́ возлюби́ти і кра́сная ми́ра сего́, любве́ ра́ди Христо́ви, возненави́діти помози́ нам; вся́ку же доброді́тель, в не́йже сам потруди́лся єси́, в сердця́х на́ших насади́ти нам посо́бствуй. Моли́ Христа́ Бо́га, да і всім правосла́вним христия́ном, в ми́рі живу́щим, просвіти́ть ум і о́чі серде́чния, є́же ко спасе́нію, утверди́ть я во ві́рі і благоче́стії і в ді́ланії за́повідей Свої́х, сохрани́ть же от ле́сти ми́ра сего́, і оставле́ніє гріхо́в да́руєть всім христия́ном, та́же і вся потре́бная ко вре́менному житію́ всім приложи́ть. Да та́ко всі христия́не, в пусти́ні і в ми́рі жи́тельствующії, ти́хоє і безмо́лвноє житіє́ поживу́ть во вся́ком благоче́стії і че́стности, і Христа́ усти́ і се́рдцем просла́в'ять, ку́пно со безнача́льним Єго́ Отце́м і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Соборові Кемеровських святих","e":"Prayer to the Synaxis of the Saints of Kemerovo","secs":[{"h":"Тропар, глас 4","ps":["Днесь ра́достно лику́єть земля́ Ке́меровськая, / прославля́ющи новому́ченики, іспові́дники, преподо́бния і пра́ведния своя́, / доброді́тельми Бо́гу послужи́вшия / і во дні гоне́нія безбо́жнаго жизнь свою́ за Христа́ положи́вшия. / Ті́мже к ним усе́рдно воззове́м: / молі́те Ми́лостиваго Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Днесь святі́ї землі́ на́шея / с на́ми предстоя́ть в Це́ркві і неви́димо за ни мо́ляться Бо́гу, / да ізба́вить нас от враг ви́димих і неви́димих, / от неду́га і гла́да, і от вся́каго зла / і спасе́ть ду́ші на́ша."]},{"h":"Молитва","ps":["При́зри, Го́споди, с висоти́ святи́я Твоєя́ на предстоя́щия лю́ди і прийми́ благодаре́ніє на́ше о Твої́х вели́ких благодія́ніїх, я́же сотвори́л єси́ со отці́ на́шими! Усли́ши нас, прославля́ющих І́м'я Твоє́ свято́є, я́ко благоволи́л єси́ просла́вити во святи́х ізбра́нния Твоя́, пра́ведники дре́внія і му́ченики но́вия, ї́хже земля́ на́ша проізрасти́ла єсть, я́ко благо́є прозябе́ніє і плод кра́сний. О, преподо́бнії і пра́веднії землі́ Ке́меровськия! Ви Го́спода Бо́га всім се́рдцем свої́м возлюби́сте і всеці́ло Єму́ угоди́сте! О, святі́ї новому́ченици землі́ на́шея! Ви во дні гоне́нія безбо́жнаго от сокро́вищниць душ ва́ших спаси́тельноє іспові́даніє Правосла́вния ві́ри ізнесли́ єсте́ і лю́дем ві́рним наста́вници до́брії яви́лися єсте́, ду́ші своя́ за Христа́ і дру́ги полага́юще. Ни́ні у́бо к вам с любо́вію прибіга́єм і мо́лимся: бу́дете небе́снії засту́пниці земно́му Оте́честву ва́шему, наставля́юще нас твори́ти во́лю Госпо́дню, во є́же преспіва́ти і нам во ві́рі, благоче́стії і любві́ христия́нстій, прославля́юще єди́нім се́рдцем і єди́німи усти́ Святу́ю, Єдиносу́щную, Животворя́щую і Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мучениці Дарії Римській","e":"Prayer to the Martyr Daria of Rome","secs":[{"h":"Тропар мучениці Дарії Римській, глас 4","ps":["Агниця Твоя, Ісусе, Дарія волає гучним голосом: «Тебе, Нареченого мій, люблю, і, Тебе шукаючи, страждаю, і розпинаюся, і погребаюся з Тобою в Твоєму хрещенні, і терплю муки за Тебе, щоб царювати в Тобі, і вмираю за Тебе, щоб і жити з Тобою; але прийми мене як жертву непорочну, з любов’ю принесену Тобі!» Її заступництвом, як Милостивий, спаси душі наші."]},{"h":"Тропар мученикам Хрисанфу й Дарії Римським, глас 7","ps":["От ю́ности ві́ру Христо́ву возлюби́л єси́, блаженіє Хриса́нфе, вра́жії пре́лести презрі́в, добро́тою Боже́ственною наслаждаєм приве́л єси́ неві́сту чи́сту Да́рію ко Христу́, і с не́ю муче́нія лю́тая прия́л єси́ му́чениче Богоприя́тне за ни моли́ся ві́рою соверша́юще па́м'ять ва́шу."]},{"h":"Кондак мучениці Дарії Римській, глас 2","ps":["Храм Твой всечестни́й я́ко цільбу́ душе́вную обрі́тше, всі ві́рнії велегла́сно вопіє́м ті, му́ченице Дарія, великоімени́тая, Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Молитва мученикам Хрисанфу й Дарії Римським","ps":["О, святі́ї і преблаже́ннії страстоте́рпці, му́ченици Христо́ві Хриса́нфе і Да́ріє! К вам у престо́ла Бо́жия предстоя́щим і моли́твенникам на́шим те́плим, ско́рим помо́щникам ми, недосто́йнії, прибіга́єм. Усли́шіте ни́ні сіє́ моле́ніє на́ше і умолі́те возлю́бленнаго ва́ми Го́спода на́шего Ісу́са Христа́, Єго́ же ви іспові́дали в тя́жких муче́ніїх свої́х пред безу́мними мучи́телі і гони́телі свято́й ві́ри Христо́вой, о нас недосто́йних грі́шних. Ви у́бо ра́ди ві́ри Христо́вой мно́гі муче́нія претерпі́ли і умерщвлени́ би́ша, Це́рков Христо́ву украси́сте і вінця́ми безсме́ртния сла́ви увенча́ннії, в неізглаго́ланній ра́дости с ли́ки а́нгельськими в небе́сних селе́ніях водворя́єтеся, Боже́ственним сві́том облиста́ємі. Яви́ти і нам многомо́щноє заступле́ніє: ві́ру Христо́ву в чистоті́ сохрани́ти, в злострада́ніях і іскуше́ніях му́жество прояви́ти, в жите́йських потре́бах дово́льство, в моли́твах постоя́нство і любо́в к Бо́гу і бли́жнім всегда́ імі́ти. Наста́віте нас, святі́ї му́ченици, моли́твами ва́шими на путь спасе́нія, укріпі́те стопи́ на́ша тве́рдо і непоколе́блемо ходи́ти путе́м за́повідей Госпо́дніх, вразумля́я заблу́ждшия, да́руя неду́гующим ісціле́ніє, бе́дствующим ізбавле́ніє, в супру́жестві живу́щим покрови́тельство, всім же нам вся ко спасе́нію поле́зная. Я́ко да ва́шими моли́твами наставля́ємі і предста́тельством укріпля́ємі, просла́вим Спаси́теля на́шего Го́спода Ісу́са Христа́. Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со безнача́льним Єго́ Отце́м і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]}];
export default D;
